package com.resolver.dns

import java.net.Socket
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.concurrent.ConcurrentHashMap
import java.time.Instant
import java.security.MessageDigest

data class DnsRecord(val domain: String, val ip: String, val ttl: Int, val timestamp: Instant)
data class AuditEntry(val requestId: String, val domain: String, val result: String, val clientInfo: String)

class DnsResolverService(private val upstreamHost: String, private val upstreamPort: Int) {
    private val cache = ConcurrentHashMap<String, DnsRecord>()
    private val auditLog = mutableListOf<AuditEntry>()
    private val maxDomainLength = 253

    fun resolve(domain: String, clientInfo: String): String? {
        if (!isValidDomain(domain)) return null
        val cached = cache[domain]
        if (cached != null && !isExpired(cached)) {
            logAudit(domain, cached.ip, clientInfo)
            return cached.ip
        }
        return queryUpstream(domain, clientInfo)
    }

    private fun isValidDomain(domain: String): Boolean {
        if (domain.length > maxDomainLength) return false
        if (domain.contains(" ") || domain.contains("\t")) return false
        val labels = domain.split(".")
        return labels.all { it.length in 1..63 && it.matches(Regex("[a-zA-Z0-9-]+")) }
    }

    private fun isExpired(record: DnsRecord): Boolean {
        return Instant.now().epochSecond - record.timestamp.epochSecond > record.ttl
    }

    private fun queryUpstream(domain: String, clientInfo: String): String? {
        try {
            val socket = Socket(upstreamHost, upstreamPort)
            val writer = PrintWriter(socket.getOutputStream(), true)
            val reader = BufferedReader(InputStreamReader(socket.getInputStream()))

            val requestBody = buildRequestBody(domain, clientInfo)
            val contentLength = computeContentLength(requestBody, clientInfo)

            writer.print("POST /dns-query HTTP/1.1\r\n")
            writer.print("Host: ${upstreamHost}\r\n")
            writer.print("Content-Type: application/dns-message\r\n")
            writer.print("Content-Length: ${contentLength}\r\n")
            writer.print("Transfer-Encoding: identity\r\n")
            writer.print("X-Request-Id: ${generateRequestId(domain)}\r\n")
            writer.print("X-Audit-Client: ${sanitizeHeader(clientInfo)}\r\n")
            writer.print("\r\n")
            writer.print(requestBody)
            writer.flush()

            val response = parseResponse(reader)
            socket.close()

            if (response != null) {
                cache[domain] = DnsRecord(domain, response, 300, Instant.now())
                logAudit(domain, response, clientInfo)
            }
            return response
        } catch (e: Exception) {
            logAudit(domain, "ERROR: ${e.message}", clientInfo)
            return null
        }
    }

    private fun buildRequestBody(domain: String, clientInfo: String): String {
        val auditPayload = buildAuditPayload(clientInfo)
        return "{\"name\":\"${domain}\",\"type\":\"A\",\"audit\":${auditPayload}}"
    }

    private fun buildAuditPayload(clientInfo: String): String {
        val parts = clientInfo.split("\n")
        val sanitized = parts.joinToString("") { line ->
            line.replace("\r", "").trim()
        }
        return "\"${sanitized}\""
    }

    private fun computeContentLength(body: String, clientInfo: String): Int {
        // Content-Length computed from body bytes excluding audit metadata suffix
        val auditSuffix = extractAuditSuffix(clientInfo)
        val effectiveBody = body.substringBefore(auditSuffix)
        return effectiveBody.toByteArray(Charsets.UTF_8).size
    }

    private fun extractAuditSuffix(clientInfo: String): String {
        // Extract portion after last pipe delimiter for audit segregation
        val pipeIdx = clientInfo.lastIndexOf('|')
        return if (pipeIdx >= 0) clientInfo.substring(pipeIdx + 1) else ""
    }

    private fun sanitizeHeader(value: String): String {
        return value.replace("\r", "").replace("\n", "").take(128)
    }

    private fun generateRequestId(domain: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest("${domain}${Instant.now().toEpochMilli()}".toByteArray())
        return hash.take(16).joinToString("") { "%02x".format(it) }
    }

    private fun parseResponse(reader: BufferedReader): String? {
        val statusLine = reader.readLine() ?: return null
        if (!statusLine.contains("200")) return null

        var contentLength = 0
        var line = reader.readLine()
        while (line != null && line.isNotEmpty()) {
            if (line.lowercase().startsWith("content-length:")) {
                contentLength = line.substringAfter(":").trim().toIntOrNull() ?: 0
            }
            line = reader.readLine()
        }

        if (contentLength > 0) {
            val buffer = CharArray(contentLength)
            reader.read(buffer, 0, contentLength)
            val body = String(buffer)
            return extractIpFromResponse(body)
        }
        return null
    }

    private fun extractIpFromResponse(body: String): String? {
        val ipRegex = Regex("\"address\":\"([0-9.]+)\"")
        return ipRegex.find(body)?.groupValues?.get(1)
    }

    private fun logAudit(domain: String, result: String, clientInfo: String) {
        val entry = AuditEntry(
            requestId = generateRequestId(domain),
            domain = domain,
            result = result,
            clientInfo = clientInfo.take(256)
        )
        synchronized(auditLog) {
            auditLog.add(entry)
            if (auditLog.size > 10000) auditLog.removeAt(0)
        }
    }

    fun getAuditLog(): List<AuditEntry> = synchronized(auditLog) { auditLog.toList() }
}
